use anyhow::Result;
use serde_json::{json, Value};

/// Mock ACP initialize handler - returns mock capabilities
pub fn handle_initialize() -> Result<Value> {
    Ok(json!({
        "protocol_version": "1.0",
        "capabilities": {
            "streaming": true,
            "permissions": true,
            "cancellation": true
        },
        "agent_info": {
            "name": "mock-agent",
            "version": "0.1.0",
            "description": "Mock ACP agent for smoke testing"
        }
    }))
}

/// Mock ACP create_session handler - returns session ID
pub fn handle_create_session() -> Result<Value> {
    Ok(json!({
        "session_id": "mock-session-123",
        "status": "ready"
    }))
}

/// Mock ACP stream_message handler - returns agent output chunks
pub fn handle_stream_message(message: &str) -> Result<Vec<Value>> {
    let chunks = vec![
        json!({
            "type": "thinking",
            "content": "Processing your request..."
        }),
        json!({
            "type": "text",
            "content": format!("Mock agent received: {}", message)
        }),
        json!({
            "type": "result",
            "content": "Mock processing complete",
            "status": "success"
        }),
    ];
    Ok(chunks)
}

/// Mock ACP cancel handler
pub fn handle_cancel(session_id: &str) -> Result<Value> {
    Ok(json!({
        "session_id": session_id,
        "status": "cancelled"
    }))
}

/// Mock ACP request_permission handler - generates approval prompt
pub fn handle_request_permission(resource: &str, action: &str) -> Result<Value> {
    Ok(json!({
        "permission_id": "perm-mock-456",
        "prompt": format!("Mock agent requests permission to {} on {}", action, resource),
        "resource": resource,
        "action": action,
        "status": "pending"
    }))
}

/// Mock ACP exit handler
pub fn handle_exit() -> Result<Value> {
    Ok(json!({
        "status": "terminated",
        "message": "Mock agent shutting down"
    }))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_initialize() {
        let result = handle_initialize().unwrap();
        assert!(result["capabilities"]["streaming"].as_bool().unwrap());
        assert_eq!(result["agent_info"]["name"], "mock-agent");
    }

    #[test]
    fn test_create_session() {
        let result = handle_create_session().unwrap();
        assert_eq!(result["session_id"], "mock-session-123");
    }

    #[test]
    fn test_stream_message() {
        let chunks = handle_stream_message("test").unwrap();
        assert_eq!(chunks.len(), 3);
        assert_eq!(chunks[0]["type"], "thinking");
        assert_eq!(chunks[2]["type"], "result");
    }

    #[test]
    fn test_cancel() {
        let result = handle_cancel("test-session").unwrap();
        assert_eq!(result["status"], "cancelled");
    }

    #[test]
    fn test_request_permission() {
        let result = handle_request_permission("file.txt", "read").unwrap();
        assert_eq!(result["resource"], "file.txt");
        assert_eq!(result["action"], "read");
        assert_eq!(result["status"], "pending");
    }

    #[test]
    fn test_exit() {
        let result = handle_exit().unwrap();
        assert_eq!(result["status"], "terminated");
    }
}

use agentic_terminal_mock_agent::{
    handle_cancel, handle_create_session, handle_exit, handle_initialize,
    handle_request_permission, handle_stream_message,
};
use anyhow::{bail, Result};
use serde_json::Value;
use std::env;
use std::io::{self, BufRead};

#[tokio::main]
async fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        eprintln!("Usage: agentic-terminal-mock-agent <command> [args...]");
        eprintln!("Commands:");
        eprintln!("  initialize");
        eprintln!("  create_session");
        eprintln!("  stream_message <message>");
        eprintln!("  cancel <session_id>");
        eprintln!("  request_permission <resource> <action>");
        eprintln!("  exit");
        eprintln!("  interactive  # read commands from stdin");
        bail!("Missing command argument");
    }

    let command = &args[1];

    match command.as_str() {
        "initialize" => {
            let result = handle_initialize()?;
            println!("{}", serde_json::to_string_pretty(&result)?);
        }
        "create_session" => {
            let result = handle_create_session()?;
            println!("{}", serde_json::to_string_pretty(&result)?);
        }
        "stream_message" => {
            if args.len() < 3 {
                bail!("stream_message requires a message argument");
            }
            let message = &args[2];
            let chunks = handle_stream_message(message)?;
            for chunk in chunks {
                println!("{}", serde_json::to_string_pretty(&chunk)?);
            }
        }
        "cancel" => {
            if args.len() < 3 {
                bail!("cancel requires a session_id argument");
            }
            let session_id = &args[2];
            let result = handle_cancel(session_id)?;
            println!("{}", serde_json::to_string_pretty(&result)?);
        }
        "request_permission" => {
            if args.len() < 4 {
                bail!("request_permission requires resource and action arguments");
            }
            let resource = &args[2];
            let action = &args[3];
            let result = handle_request_permission(resource, action)?;
            println!("{}", serde_json::to_string_pretty(&result)?);
        }
        "exit" => {
            let result = handle_exit()?;
            println!("{}", serde_json::to_string_pretty(&result)?);
        }
        "interactive" => {
            run_interactive_mode()?;
        }
        _ => {
            bail!("Unknown command: {}", command);
        }
    }

    Ok(())
}

fn run_interactive_mode() -> Result<()> {
    eprintln!("Mock ACP Agent - Interactive Mode");
    eprintln!("Enter commands in JSON format or 'exit' to quit");
    eprintln!("Example: {{\"command\": \"initialize\"}}");

    let stdin = io::stdin();
    for line in stdin.lock().lines() {
        let line = line?;
        let line = line.trim();

        if line.is_empty() {
            continue;
        }

        if line == "exit" || line == "quit" {
            let result = handle_exit()?;
            println!("{}", serde_json::to_string_pretty(&result)?);
            break;
        }

        match parse_and_execute(line) {
            Ok(output) => println!("{}", serde_json::to_string_pretty(&output)?),
            Err(e) => eprintln!("Error: {}", e),
        }
    }

    Ok(())
}

fn parse_and_execute(input: &str) -> Result<Value> {
    let parsed: Value = serde_json::from_str(input)?;
    let command = parsed["command"]
        .as_str()
        .ok_or_else(|| anyhow::anyhow!("Missing 'command' field"))?;

    match command {
        "initialize" => handle_initialize(),
        "create_session" => handle_create_session(),
        "stream_message" => {
            let message = parsed["message"]
                .as_str()
                .ok_or_else(|| anyhow::anyhow!("Missing 'message' field"))?;
            let chunks = handle_stream_message(message)?;
            Ok(serde_json::json!({ "chunks": chunks }))
        }
        "cancel" => {
            let session_id = parsed["session_id"]
                .as_str()
                .ok_or_else(|| anyhow::anyhow!("Missing 'session_id' field"))?;
            handle_cancel(session_id)
        }
        "request_permission" => {
            let resource = parsed["resource"]
                .as_str()
                .ok_or_else(|| anyhow::anyhow!("Missing 'resource' field"))?;
            let action = parsed["action"]
                .as_str()
                .ok_or_else(|| anyhow::anyhow!("Missing 'action' field"))?;
            handle_request_permission(resource, action)
        }
        "exit" => handle_exit(),
        _ => bail!("Unknown command: {}", command),
    }
}
